cd /workspace && cat > /tmp/verify_graph.mjs <<'EOF'
const BASE='http://localhost:5173';
let seen=new Set(), failed=[], ok=0;
async function fetchT(url){ try{ const r=await fetch(BASE+url,{signal:AbortSignal.timeout(20000)}); const t=await r.text(); return {status:r.status,text:t}; }catch(e){ return {status:'ERR',text:String(e)}; } }
async function walk(url){
  if(seen.has(url))return; seen.add(url);
  const {status,text}=await fetchT(url);
  if(status!==200){ failed.push(`${url} -> HTTP ${status}`); return; }
  const m=text.match(/"message":"([^"]+)"/);
  if(m && /Failed to resolve|no such file|import/i.test(m[1])){ failed.push(`${url} -> ${m[1]}`); return; }
  ok++;
  const specs=[];
  for(const mm of text.matchAll(/import\s*\(\s*["']([^"']+)["']\s*\)/g)) specs.push(mm[1]);
  for(const mm of text.matchAll(/from\s+["']([^"']+)["']/g)) specs.push(mm[1]);
  for(const mm of text.matchAll(/import\s+["']([^"']+)["']/g)) specs.push(mm[1]);
  const segs=url.split('/').filter(Boolean);
  const dir=segs.slice(0,-1);
  for(let s of new Set(specs)){
    let t=null;
    if(s.startsWith('./')||s.startsWith('../')){
      const parts=dir.concat(s.split('/'));
      const out=[];
      for(const p of parts){ if(p==='.') continue; if(p==='..') out.pop(); else out.push(p); }
      t='/'+out.join('/');
    } else if(s.startsWith('@/')){ t='/resources/js/'+s.slice(2); }
    else if(s.startsWith('/')||s.startsWith('@vite')){ t=s; }
    else continue; // bare module specifier (node_modules)
    await walk(t);
  }
}
await walk('/resources/js/app.ts');
console.log('Modules resolved OK:', ok);
console.log('FAILED imports:', failed.length);
for(const f of [...new Set(failed)]) console.log('  ', f);
EOF
node /tmp/verify_graph.mjs 2>&1 | head -40; echo "NODE_EXIT=${PIPESTATUS[0]}"
